public enum YachiyoThemeID: String, CaseIterable, Sendable {
    case mizu
    case sumi
    case ume
    case aoba
    case mint
    case fuji
    case yamabuki
    case gobyou
    case murasaki

    public var displayName: String {
        switch self {
        case .mizu: return "Mizu"
        case .sumi: return "Sumi"
        case .ume: return "Ume"
        case .aoba: return "Aoba"
        case .mint: return "Mint"
        case .fuji: return "Fuji"
        case .yamabuki: return "Yamabuki"
        case .gobyou: return "Gobyou"
        case .murasaki: return "Murasaki"
        }
    }
}

